namespace App\Http\Resources;

use Illuminate\Http\Request;
use Illuminate\Http\Resources\Json\JsonResource;

class TenantApplicationResource extends JsonResource
{
    public function toArray(Request $request): array
    {
        $isAuthorizedUnderwriter = $request->user()?->can('viewCreditDetails', $this->resource);

        return [
            'application_id' => $this->id,
            'applicant_name' => $this->full_name,
            'social_security_number' => $this->when($isAuthorizedUnderwriter, $this->ssn),
            'credit_score' => $this->when($isAuthorizedUnderwriter, $this->experian_fico_score),
            'monthly_gross_income' => $this->monthly_income,
            'submission_status' => $this->status
        ];
    }
}
